  async deleteHarvestLog(harvestIdOrAnimal: string, confirm: boolean): Promise<void> {
    await this.withHeal(this.deleteButtonFor(harvestIdOrAnimal), (l) => l.click(), `Delete Harvest Log: ${harvestIdOrAnimal}`);
    if (confirm) {
      await this.withHeal(this.confirmDeleteButton, (l) => l.click(), 'Confirm Delete Button');
    } else {
      await this.withHeal(this.cancelDeleteButton, (l) => l.click(), 'Cancel Delete Button');
    }
  }

